-- food menu snapshots, batch 1 (25 menus)
with target as (
  select slug from venues where slug = 'luna-and-sol-pilates-yoga' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Membership and Classes', 1, 'draft', 'partial', 'https://luna-solpilates.com/membership', 'Official Luna & Sol Pilates - Yoga menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '5bfc773ef7b923cc2be5e4de84014ce21d2b0895922d20a5e92d6baa5e3d8186', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Membership', 0), ('Private Class', 1), ('Casual Classes', 2), ('Subscriptions', 3)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Membership', 'Intro Offer', '3 Credits, 14 days validity', 550000, 'IDR', 0), ('Private Class', 'Private Reformer Session', 'Flexible scheduling', 900000, 'IDR', 0), ('Private Class', 'Private Yoga/Mat Session', 'Flexible scheduling', 700000, 'IDR', 1), ('Casual Classes', 'Casual Reformer Class', 'Open for all level, One time Booking', 300000, 'IDR', 0), ('Casual Classes', 'Casual Mat/Yoga Class', 'Open for all level, One time Booking', 250000, 'IDR', 1), ('Subscriptions', 'Bi-Annual Membership', 'Valid for 6 Months: Unlimited class credits, Unlimited outlet access credits, Credits are renewed every day with no rollover, 2 class bookings per day', 20000, 'IDR', 0), ('Subscriptions', 'Annual Membership', 'Valid for 12 Months: Unlimited class credits, Unlimited outlet access credits, Credits are renewed every day with no rollover, 2 class bookings per day', 38000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

