insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('All Treatments', 'Cream Bath', 'Embark on a truly Balinese experience by indulging in the luxurious tradition of a Cream Bath ritual. Not to be missed on your Bali itinerary, this experience encompasses a blissful combination of rich heritage and modern hair care. Our carefully curated hair mask, free from harmful toxins, blends the hydrating properties of aloe vera, the nourishing essence of avocado extracts and the replenishin', 500000, 'IDR', 0), ('All Treatments', 'Scalp Ritual', 'Surrender to a holistic experience with our transformative botanical journey and embody the revitalizing spirit of our plant-powered, toxin-free Scalp Ritual. Let our skilled therapists melt away tension in your neck, head and shoulders by reactivating blood circulation. Infused with a soothing fusion of avocado and ginseng extracts, our potent elixir nurtures your scalp naturally for a renewed se', 500000, 'IDR', 1), ('All Treatments', 'Scalp Ritual (Oil Free)', 'Let our skilled therapists work their magic as they gently massage your scalp, relieving tension and promoting relaxation. This oil-free treatment is designed to enhance blood circulation and ease headaches, leaving you refreshed and rejuvenated.', 300000, 'IDR', 2), ('All Treatments', 'Quick Glow', 'Indulge in a rejuvenating Express Facial Massage, designed for those seeking a quick retreat from their daily hustle or for individuals looking to experience the soothing benefits of facial massage for the first time. Our expert therapists will gently stimulate circulation in your facial, neck and head regions, as delicate strokes and gentle pressure work to revitalize your skin and invigorate you', 300000, 'IDR', 3), ('All Treatments', 'Sparkling Iceballs', 'Indulge in our luxurious plant-derived, toxic-free Pressure Point Facial Massage, a revitalizing spa ritual specifically designed to rejuvenate your skin and relax your mind. This therapeutic facial massage targets key pressure points on the face, promoting increased circulation and stimulating relaxation to enhance your overall well-being. By activating these pressure points, the massage encourag', 600000, 'IDR', 4), ('All Treatments', 'Natural Dreams', 'Embark on a rejuvenating journey with our non-invasive traditional cleansing facial that harnesses the potent benefits of plant-derived ingredients, entirely free from toxins. Enjoy a serene escape as your skin is treated to a purifying cleanse, a tranquil facial massage, gentle exfoliation scrub, and a decadent nourishing mask, leaving you with a fresh, radiant glow.', 800000, 'IDR', 5), ('All Treatments', 'The Healing Act', 'Experience a blend of traditional Balinese body massage techniques, including soothing rhythmic strokes that promote inner relaxation. Our specially formulated plant-based massage oil infused with calming notes of rose, black pepper & frankincense essential oils promotes deep relaxation, muscle recovery and holistic well-being.', 400000, 'IDR', 6), ('All Treatments', 'The Panel Beat', 'Unleash the ultimate rejuvenating experience with The Panel Beat, a massage technique that sets the benchmark for deep tissue therapy. Perfect for surf enthusiasts looking to unwind after a day of exhilarating barrel rides. Indulge in a 90 min session for an extended journey into relaxation.', 500000, 'IDR', 7), ('All Treatments', 'The Ultimate Euphoria', 'Allow us to calm your senses with our gentle yet deeply relaxing bespoke signature body massage, meticulously crafted with plant-derived non-toxic ingredients sourced exclusively from within the Indonesian archipelago. Immerse yourself in a state of blissful tranquility as you ease muscle tension and detoxify your body.', 800000, 'IDR', 8), ('All Treatments', 'Back In Harmony', 'Experience the ultimate indulgence with our tailored therapeutic massage, meticulously crafted to target tension and tightness in your back, shoulders, and neck. This specialized treatment is expertly designed to dissolve stress and promote relaxation under the skilled hands of our therapists.', 500000, 'IDR', 9), ('All Treatments', 'The Mum To Be', 'Experience the soothing comfort of our specially curated Pregnancy Massage, expertly delivered by our skilled and caring therapists. This treatment is tailored to alleviate the discomforts of pregnancy and promote relaxation.', 600000, 'IDR', 10), ('All Treatments', 'A Salty Ritual', 'Indulge in a truly Balinese spa experience with our Sea Salt Scrub ritual, enriched with local calendula flowers and hand-harvested Balinese sea salt. This ritual offers holistic renewal of your skin.', 550000, 'IDR', 11), ('All Treatments', 'Botanical Bliss', 'Embark on a sensory journey with our Indonesian-inspired Sugar Scrub Ritual, featuring an exotic blend of locally sourced ingredients that capture the essence of Indonesia''s rich botanicals. Our sugar-based scrub is mindfully formulated to be plant-powered and toxic-free.', 550000, 'IDR', 12), ('All Treatments', 'Awaken Your Senses', 'Soothe and restore sun-exposed skin with our Luxe Botanical Body Mask, a deeply replenishing spa experience crafted from locally sourced, plant-derived, toxin-free ingredients. Unwind as the mask envelops your skin in botanical richness, leaving it soft, hydrated, and radiant.', 550000, 'IDR', 13), ('All Treatments', 'Relaxology', 'Indulge in our Calming Foot Massage, a blissful experience tailored for relaxation enthusiasts. Our skilled therapists will envelop you with gentle, soothing strokes, designed to alleviate tension in your feet and lower legs.', 300000, 'IDR', 14), ('All Treatments', 'Reflexology', 'Immerse yourself in our blissful Foot Reflexology, applying targeted pressure to specific points on your feet, aligning with various organs and systems of the body. Experience improved circulation and increased energy flow.', 300000, 'IDR', 15), ('All Treatments', 'Therapeutic Manicure', 'Revitalize your nails and hands with our Therapeutic Manicure, a wellness-focused experience that embraces the power of nature. Our skilled technicians expertly shape and buff your nails, ensuring a flawless result followed by gentle exfoliation.', 500000, 'IDR', 16), ('All Treatments', 'Therapeutic Pedicure', 'Immerse yourself in ultimate self-care with our Therapeutic Pedicure, prioritizing your well-being with only plant-based, non-toxic products throughout the treatment.', 500000, 'IDR', 17), ('All Treatments', 'Two Slices Of Heaven', 'Enhance your spa experience with our deluxe package, which includes The Healing Act 60 min massage along with your choice of a body scrub or mask. Your experience kicks off with a calming 5 min Foot Ritual.', 800000, 'IDR', 18), ('All Treatments', 'Three Slices Of Heaven', 'Embark on a profound self-care journey with our ultimate spa experience, including The Healing Act 60 min massage, our luxurious Sparkling Iceballs Facial, and a choice from our selection of 60 min The Crown rituals.', 1300000, 'IDR', 19), ('All Treatments', 'The Art Of Giving', 'With our Holistic Indulgence Cards, you are not just giving a gift – you are giving a transformative experience that promotes inner harmony and outer radiance. Let your loved ones unwind, recharge and reconnect with themselves.', null, null, 20), ('The Art Of Giving', 'Holistic Indulgence Card', 'With our Holistic Indulgence Cards, you are not just giving a gift – you are giving a transformative experience that promotes inner harmony and outer radiance. Let your loved ones unwind, recharge, and reconnect with themselves in a serene sanctuary dedicated to holistic wellness.', null, null, 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

