insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Sound Healing', 'Sound Healing Journey', 'Simply lie down and close your eyes to receive the sounds in this private healing journey. The sounds of Tibetan singing bowls and various other instruments such as tuning forks, chimes, and bells help you to slow down your brain waves and relax deeply. Sound healing is based on the principle that everything is vibration and that sound can help us to realign with our natural harmonic state of bein', 1920000, 'IDR', 0), ('Water Healing Treatment', 'Water Healing Treatment', 'The Water Healing treatment at Udara can be one of the most memorable and unique experiences you have ever had. The therapist will support, hold and move your body in the warm water pool, drawing from Aquatic Bodywork modalities such as Watsu, Water Dance or Healing Dance. Moments of stillness alternate with rhythmical flowing movements, which free the whole body and the mind. We recall our cellul', 1920000, 'IDR', 0), ('Reiki', 'Reiki', 'In a Reiki session, the practitioner transfers energy through their hands by placing them over or on various body parts. To receive the session, you are comfortably lying on a massage bed, fully clothed. The universal Reiki energy can help improve energy flow in the body, induce deep relaxation, balance emotions and speed up the body''s natural healing processes. It is a subtle healing modality tha', 1040000, 'IDR', 0), ('Water Massage', 'Water Massage', 'Enter into the 35-degree warm pool of our Spa facilities to receive a unique massage session floating on the surface of the water. This treatment combines gentle stretches with acupressure massage to release muscular tension, increase range of motion and relieve pressure from joints. Floating pillows allow you to completely let go and soft underwater music will help you relax deeply. Receiving bod', 1120000, 'IDR', 0), ('Hyperbaric Oxygen Chamber Treatment (HBOT)', 'Hyperbaric Oxygen Chamber Treatment (HBOT)', 'Bring your health and well-being to an optimum level with Hyperbaric Oxygen Therapy. This new treatment involves breathing almost pure oxygen in a pressurized chamber to treat various health conditions and improve quality of life. During this treatment your lungs can gather much more oxygen than would be possible breathing oxygen at normal air pressure. Increasing your oxygenation levels has shown', 1120000, 'IDR', 0), ('Acupuncture', 'Acupuncture', 'Acupuncture has its roots in ancient Chinese medicine. Fine needles are inserted at certain points in the body to treat many types of health conditions and improve overall wellness. Acupuncture is based on the belief that energy (Qi) flows through the body in channels called meridians. An imbalance or blocked flow of this life force may lead to illness.', 1040000, 'IDR', 0), ('Cupping', 'Cupping', 'Cupping therapy is one of the oldest therapies in the world, going back to ancient Egypt scriptures from 1550 BC. The therapist places cups on your back, stomach, arms or legs, and a vacuum pulls the skin upward.', 1040000, 'IDR', 0), ('Hypnotherapy', 'Hypnotherapy', 'Feeling stuck in a negative loop of thoughts, behaviors, feelings, relationships, or situations? Hypnotherapy can help turn your life around. Diving into your subconscious mind allows you to access, understand, and heal.', 3760000, 'IDR', 0), ('Quit Smoking with Hypnosis', 'Quit Smoking', 'Hypnotherapy is one of the most successful modalities to help you be FREE of Cigarettes. This package includes 5 sessions designed to help you quit smoking.', 15760000, 'IDR', 0), ('Healing Breathwork', 'Healing Breathwork', 'A private session with Gus Wira, focusing on removing blockages, improving capacity, and releasing binding patterns.', 1920000, 'IDR', 0), ('Your Voice, Your Mirror', 'Your Voice, Your Mirror', 'A vocal lesson and exploration journey combined with Theta Healing treatments to remove the blocks to your truest expression.', 4560000, 'IDR', 0), ('Theta Healing', 'Theta Healing', 'A unique way to reprogram the subconscious mind and integrate challenging experiences. The session helps identify and address underlying patterns in your life.', 3520000, 'IDR', 0), ('Dream Machine', 'Dream Machine', 'A stroboscopic light and sound healing experience that promotes relaxation, meditation, and activation of various brainwave states.', 2240000, 'IDR', 0), ('Personal Training', 'Personal Training', 'Including nutrition counseling with our certified Personal Trainer and Nutrition Consultant. Tailored training plan to achieve fitness goals effectively.', 1152000, 'IDR', 0), ('Kundalini Activation & Bodywork', 'Kundalini Activation & Bodywork', 'Join Saida for a transformational session designed for those seeking profound healing and higher consciousness.', 4240000, 'IDR', 0), ('Aerial Thai Massage', 'Aerial Thai Massage', 'Experience a unique fusion of Thai Massage and Aerial Yoga that promotes relaxation and restores energy.', 1088000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

